/* A loopback TCP/IP offload engine for the regression suite.

   NX_ENABLE_TCPIP_OFFLOAD hands nine socket operations to the interface's
   nx_interface_tcpip_offload_handler and expects the driver to report results
   back through _nx_tcp_socket_driver_establish,
   _nx_tcp_socket_driver_packet_receive and _nx_udp_socket_driver_packet_receive.
   Before this file the suite had no such driver, so every one of those paths
   was compiled in three configurations and executed in none.

   The engine carries no protocol. It matches endpoints by port, moves the
   sender's packet to the peer and reports the transitions. That is enough to
   drive the offload code under test, which is the point: the protocol being
   bypassed is exactly what offload means.

   Outside NX_ENABLE_TCPIP_OFFLOAD this file compiles to nothing, so it is
   linked into test_utility unconditionally. */

#ifndef NX_TCPIP_OFFLOAD_DRIVER_H
#define NX_TCPIP_OFFLOAD_DRIVER_H

#include "nx_api.h"

#ifdef NX_ENABLE_TCPIP_OFFLOAD

/* How the engine answers NX_TCPIP_OFFLOAD_TCP_CLIENT_SOCKET_CONNECT.

   All three are reachable states of real offload hardware and each selects a
   different arm of _nxd_tcp_client_socket_driver_connect: NX_SUCCESS takes the
   immediate-establish arm, NX_IN_PROGRESS takes the NX_TCP_SYN_SENT arm and
   completes later from the engine thread, and a refusal takes the arm that
   unwinds the connection counters and returns NX_TCPIP_OFFLOAD_ERROR. */
#define NX_TCPIP_OFFLOAD_CONNECT_IMMEDIATE  0
#define NX_TCPIP_OFFLOAD_CONNECT_IN_PROGRESS 1
#define NX_TCPIP_OFFLOAD_CONNECT_REFUSE     2

/* Selects the connect behaviour above. A test sets it before connecting. */
extern UINT nx_tcpip_offload_connect_mode;

/* When NX_TRUE every subsequent NX_TCPIP_OFFLOAD_TCP_SOCKET_SEND and
   NX_TCPIP_OFFLOAD_UDP_SOCKET_SEND fails, which is the only way to reach the
   NX_TCPIP_OFFLOAD_ERROR returns in the two send paths. */
extern UINT nx_tcpip_offload_send_failure;

/* When NX_TRUE the next NX_TCPIP_OFFLOAD_UDP_SOCKET_BIND fails, which drives
   _nx_udp_socket_bind's unwind through _nx_udp_socket_unbind. */
extern UINT nx_tcpip_offload_bind_failure;

/* When NX_TRUE the next NX_TCPIP_OFFLOAD_TCP_SERVER_SOCKET_LISTEN fails. */
extern UINT nx_tcpip_offload_listen_failure;

/* Counts handler invocations per operation, so a test can assert that the
   operation it meant to drive was the one that ran. Indexed by the
   NX_TCPIP_OFFLOAD_* operation codes, which run 0..8. */
#define NX_TCPIP_OFFLOAD_OPERATION_COUNT 9
extern ULONG nx_tcpip_offload_operations[NX_TCPIP_OFFLOAD_OPERATION_COUNT];

/* Resets the engine: every endpoint freed, every knob back to its default and
   every counter zeroed. Called from a test's thread entry before it builds
   anything, because the suite runs one test per process but the engine's state
   is file scope and a test that failed half way through must not leak into the
   assertions of the next thing this process does. */
VOID nx_tcpip_offload_driver_reset(VOID);

/* The link driver entry point. Pass it to nx_ip_create in place of
   _nx_ram_network_driver: it answers the link commands an offload interface
   needs and installs the offload handler and its capability flag during
   NX_LINK_INTERFACE_ATTACH, which is where nx_ip_interface_attach.c and
   nx_ip_thread_entry.c read them. */
VOID nx_tcpip_offload_driver(NX_IP_DRIVER *driver_req_ptr);

#endif /* NX_ENABLE_TCPIP_OFFLOAD */

#endif /* NX_TCPIP_OFFLOAD_DRIVER_H */
